args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?birthDate ?label WHERE {
  VALUES ?person { dbr:Ryan_Tubridy dbr:Mauro_Massironi }
  OPTIONAL { ?person dbo:birthDate ?bd1. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  BIND(coalesce(?bd1, ?bd2) as ?birthDate)
  FILTER(bound(?birthDate))
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
}
ORDER BY xsd:date(?birthDate)
LIMIT 1

